212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Visit visit = visitMapper.toVisit(visitFieldsDto);
217	        Pet pet = new Pet();
218	        pet.setId(petId);
219	        visit.setPet(pet);
220	        this.clinicService.saveVisit(visit);
221	        VisitDto visitDto = visitMapper.toVisitDto(visit);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
223	            .buildAndExpand(visit.getId()).toUri());
224	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
225	    }
226	
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner != null) {
233	            Pet pet = owner.getPet(petId);
234	            if (pet != null) {
235	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    /**
242	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
243	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
244	     * does not catch). The names of all offending fields are collected so the caller receives a
245	     * 400 response whose {@code errors} array lists each one.
246	     */
247	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
248	        List<String> missingFields = new ArrayList<>();
249	        if (isBlank(ownerFieldsDto.getFirstName())) {
250	            missingFields.add("firstName");
251	        }
252	        if (isBlank(ownerFieldsDto.getLastName())) {
253	            missingFields.add("lastName");
254	        }
255	        if (isBlank(ownerFieldsDto.getAddress())) {
256	            missingFields.add("address");
257	        }
258	        if (isBlank(ownerFieldsDto.getCity())) {
259	            missingFields.add("city");
260	        }
261	        if (isBlank(ownerFieldsDto.getTelephone())) {
262	            missingFields.add("telephone");
263	        }
264	        if (!missingFields.isEmpty()) {
265	            throw new InvalidOwnerFieldsException(missingFields);
266	        }
267	    }
268	
269	    private static boolean isBlank(String value) {
270	        return value == null || value.trim().isEmpty();
271	    }
272	
273	    /**
274	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
275	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
276	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
277	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
278	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
279	     * means an address that is blank after normalization is rejected like a missing one.
280	     */
281	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
282	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
283	    }
284	
285	    /**
286	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
287	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
288	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
289	     * address is returned unchanged, making it safe to apply to stored values during comparison.
290	     */
291	    private static String canonicalAddress(String address) {
292	        if (address == null) {
293	            return null;
294	        }
295	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
296	        if (collapsed.isEmpty()) {
297	            return "";
298	        }
299	        String[] tokens = collapsed.split(" ");
300	        StringBuilder sb = new StringBuilder(collapsed.length());
301	        for (int i = 0; i < tokens.length; i++) {
302	            if (i > 0) {
303	                sb.append(' ');
304	            }
305	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
306	        }
307	        return sb.toString();
308	    }
309	
310	    /**
311	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
312	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
313	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
314	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
315	     * string is written back onto the request so it is what gets stored and returned. Any value that
316	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
317	     * names {@code telephone}.
318	     */
319	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
320	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
321	    }
322	
323	    /**
324	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
325	     * (400) naming {@code telephone} when it cannot form a valid number.
326	     */
327	    private static String toE164(String telephone) {
328	        if (telephone == null) {
329	            throw new InvalidOwnerFieldsException(List.of("telephone"));
330	        }
331	        boolean hasCountryCode = telephone.trim().startsWith("+");
332	        String digits = telephone.replaceAll("\\D", "");
333	        String national;
334	        if (hasCountryCode) {
335	            national = digits;
336	        } else {
337	            if (digits.startsWith("0")) {
338	                digits = digits.substring(1);
339	            }
340	            national = "61" + digits;
341	        }
342	        if (!national.matches("[0-9]{8,15}")) {
343	            throw new InvalidOwnerFieldsException(List.of("telephone"));
344	        }
345	        return "+" + national;
346	    }
347	
348	    /**
349	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
350	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
351	     * each existing owner's stored telephone is converted the same way before comparison so numbers
352	     * that only differ in formatting still collide. A match results in a 409 response naming
353	     * {@code telephone}.
354	     */
355	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
356	        String telephone = ownerFieldsDto.getTelephone();
357	        for (Owner existing : this.clinicService.findAllOwners()) {
358	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
359	                throw new DuplicateOwnerTelephoneException(telephone);
360	            }
361	        }
362	    }
363	
364	    /**
365	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
366	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
367	     */
368	    private static String normalizeExisting(String telephone) {
369	        try {
370	            return toE164(telephone);
371	        } catch (InvalidOwnerFieldsException ex) {
372	            return null;
373	        }
374	    }
375	
376	    /**
377	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
378	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
379	     * single space, so values that differ only in letter case or spacing still collide. When the
380	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
381	     * household members to share a name and address. A match results in a 409 response naming
382	     * {@code lastName} and {@code address}.
383	     */
384	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
385	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
386	            return;
387	        }
388	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
389	        String address = canonicalAddress(ownerFieldsDto.getAddress());
390	        for (Owner existing : this.clinicService.findAllOwners()) {
391	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
392	                && address.equals(canonicalAddress(existing.getAddress()))) {
393	                throw new DuplicateOwnerHouseholdException(
394	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
395	            }
396	        }
397	    }
398	
399	    /**
400	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
401	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
402	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
403	     */
404	    private static String normalizeForComparison(String value) {
405	        if (value == null) {
406	            return "";
407	        }
408	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
409	    }
410	
411	    /**
412	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
413	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
414	     * written back onto the request so that is what gets stored and returned. A present but invalid
415	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
416	     */
417	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
418	        String email = ownerFieldsDto.getEmail();
419	        if (email == null) {
420	            return;
421	        }
422	        String trimmed = email.trim();
423	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
424	            throw new InvalidOwnerFieldsException(List.of("email"));
425	        }
426	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
427	    }
428	
429	    /**
430	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
431	     * it is set to the server's current date so every owner is persisted with a registration date;
432	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
433	     * {@code YYYY-MM-DD} format.
434	     */
435	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
436	        if (ownerFieldsDto.getRegistrationDate() == null) {
437	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
438	        }
439	    }
440	
441	    /**
442	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
443	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
444	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
445	     * (e.g. {@code 'SMI-0007'}).
446	     */
447	    private void assignCustomerCode(Owner owner) {
448	        String lastName = owner.getLastName();
449	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
450	        int sequence = this.clinicService.findAllOwners().size() + 1;
451	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
452	    }
453	
454	    /**
455	     * Assigns the new owner's {@code householdId} when the request opts in with
456	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
457	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
458	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
459	     * all end up carrying one stable shared identifier: if any existing member already has a
460	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
461	     * and address. Any existing member that is missing the identifier is updated so the whole
462	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
463	     * identifier is assigned.
464	     */
465	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
466	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
467	            return;
468	        }
469	        String lastName = normalizeForComparison(owner.getLastName());
470	        String address = canonicalAddress(owner.getAddress());
471	        List<Owner> members = new ArrayList<>();
472	        for (Owner existing : this.clinicService.findAllOwners()) {
473	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
474	                && address.equals(canonicalAddress(existing.getAddress()))) {
475	                members.add(existing);
476	            }
477	        }
478	        if (members.isEmpty()) {
479	            return;
480	        }
481	        String householdId = members.stream()
482	            .map(Owner::getHouseholdId)
483	            .filter(id -> id != null && !id.isBlank())
484	            .findFirst()
485	            .orElseGet(() -> newHouseholdId(lastName, address));
486	        owner.setHouseholdId(householdId);
487	        for (Owner member : members) {
488	            if (!householdId.equals(member.getHouseholdId())) {
489	                member.setHouseholdId(householdId);
490	                this.clinicService.saveOwner(member);
491	            }
492	        }
493	    }
494	
495	    /**
496	     * Derives a stable household identifier from the normalized last name and address: the first
497	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
498	     * owners in the same household therefore derive the same value regardless of creation order.
499	     */
500	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
501	        try {
502	            byte[] digest = MessageDigest.getInstance("SHA-256")
503	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
504	            StringBuilder hex = new StringBuilder(digest.length * 2);
505	            for (byte b : digest) {
506	                hex.append(String.format("%02x", b));
507	            }
508	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
509	        } catch (NoSuchAlgorithmException ex) {
510	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
511	        }
512	    }
513	}
